messages.content:
Tool response:
Tool: create_dependent_task
Description: Create Dependent Task
Parameters:
    {
      "type": "object",
      "properties": {
        "project_id": {
          "type": "integer",
          "description": "Internal ID of the project",
          "title": "Project Id"
        },
        "phase_id": {
          "type": "integer",
          "description": "Internal ID of the phase",
          "title": "Phase Id"
        },
        "name": {
          "type": "string",
          "title": "Name",
          "description": "Name of the new task"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Description",
          "description": "Description of the new task"
        },
        "start_date": {
          "type": "string",
          "title": "Start Date",
          "description": "Start date of the task in YYYY-MM-DD format"
        },
        "due_date": {
          "type": "string",
          "title": "Due Date",
          "description": "Due date of the task in YYYY-MM-DD format"
        },
        "priority": {
          "type": "string",
          "title": "Priority",
          "description": "Priority level of the task (Low, Medium, High, Critical)"
        },
        "depends_on_task_id": {
          "type": "integer",
          "title": "Depends On Task Id",
          "description": "ID of the task that this task depends on"
        }
      },
      "required": [
        "project_id",
        "phase_id",
        "name",
        "start_date",
        "due_date",
        "priority",
        "depends_on_task_id"
      ]
    }
